    lay("<html style='font-size:calc(1em + 2px);line-height:20.6px'><body style='margin:0'><div id=p style='font-size:small;line-height:1.5em'><div id=e style='width:2.7rem;font-size:64px;line-height:2ex'>x</div></div></body></html>");
