    lay("<html style='font-size:2ex;line-height:calc(1em + 4px)'><body style='margin:0'><div id=p style='font-size:128.34%'><div id=e style='font-size:0lh;text-indent:10.58lh;text-indent:5.28REM'>x</div></div></body></html>");
    font_lh("p", 13, 1283, 14, 0, 0);
    font_lh("e", 13, 1283, 14, 0, 0);
    TEST_ASSERT_EQUAL(53, el("e")->text_indent);
    lay("<html style='font-size:138.7%;line-height:calc(1rem + 1ex)'><body style='margin:0'><div id=p style='font-size:12'><div id=e style='height:9EX;height:10ex;font-size:1.25em'>x</div></div></body></html>");
    font_lh("p", 22, 2219, 24, 0, 0);
    font_lh("e", 28, 2774, 24, 0, 0);
    TEST_ASSERT_EQUAL(90, el("e")->h);
    lay("<html style='line-height:calc(120% - 2px)'><body style='margin:0'><div id=p style=''><div id=e style='font-size:2zz;width:rem'>x</div></div></body></html>");
