    TEST_ASSERT_EQUAL(-122, el("e")->margin[3]);
    lay("<html style='font-size:clamp(10px, 1.5em, 30px)'><body style='margin:0'><div id=p style='font-size:0px;line-height:120%'><div id=e style='padding-left:9.16cap;line-height:calc(1rem + 1ex);font-size:2.128cap'>x</div></div></body></html>");
